package dndcharacter

import (
	"math/rand"
	"sort"
	"time"
)

// rng is a package-level generator so the character generator is random
// regardless of the Go version / go directive (top-level math/rand is
// deterministically seeded when the module targets a pre-1.20 go version).
var rng = rand.New(rand.NewSource(time.Now().UnixNano()))

type Character struct {
	Strength     int
	Dexterity    int
	Constitution int
	Intelligence int
	Wisdom       int
	Charisma     int
	Hitpoints    int
}

// Modifier calculates the ability modifier for a given ability score.
// It is the score minus 10, divided by 2, rounded down (toward negative
// infinity), which matches the D&D rules for negative values.
func Modifier(score int) int {
	d := score - 10
	if d < 0 {
		// Shift so that integer division (which truncates toward zero)
		// behaves like a floor for negative numbers.
		d--
	}
	return d / 2
}

// Ability uses randomness to generate the score for an ability by rolling
// four 6-sided dice and keeping the sum of the three highest.
func Ability() int {
	dice := make([]int, 4)
	for i := range dice {
		dice[i] = rng.Intn(6) + 1
	}
	sort.Ints(dice)
	return dice[1] + dice[2] + dice[3]
}

// GenerateCharacter creates a new Character with random scores for abilities
// and hitpoints derived from the constitution score.
func GenerateCharacter() Character {
	constitution := Ability()
	return Character{
		Strength:     Ability(),
		Dexterity:    Ability(),
		Constitution: constitution,
		Intelligence: Ability(),
		Wisdom:       Ability(),
		Charisma:     Ability(),
		Hitpoints:    10 + Modifier(constitution),
	}
}

